import { motion } from 'framer-motion';
import { ExternalLink, CheckCircle2 } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';

import type { Article, Project } from '../../types/common';
import { optimizeImageUrl } from '../../utils/imageUrl';

import VideoEmbed from './VideoEmbed';

interface ContentBodyProps {
  content: Article | Project;
  type: 'article' | 'project';
  onTagClick: (tag: string) => void;
}

export default function ContentBody({ content, type, onTagClick }: ContentBodyProps) {
  return (
    <>
      {content.tags && content.tags.length > 0 && (
        <div className="lg:col-span-2 flex flex-wrap gap-2 mb-8">
          {content.tags.map((tag, index) => (
            <button
              key={index}
              onClick={() => onTagClick(tag)}
              className="px-2.5 py-1 bg-primary/10 dark:bg-primary/20 text-primary-dark dark:text-primary-light rounded-full text-sm hover:bg-primary/20 dark:hover:bg-primary/30 transition-colors"
            >
              {tag}
            </button>
          ))}
        </div>
      )}

      <div className="grid lg:grid-cols-2 gap-8 mb-12">
        <div className="relative rounded-xl overflow-hidden h-full min-h-[400px]">
          <img
            src={optimizeImageUrl(content.image || '', 1200)}
            alt={content.title}
            className="absolute inset-0 w-full h-full object-cover"
            width={1200}
            height={675}
            loading="eager"
            decoding="async"
          />
        </div>

        <div className="bg-gray-50 dark:bg-neutral-darker rounded-xl p-6 h-full min-h-[400px] space-y-6">
          {content.keyPoints && content.keyPoints.length > 0 && (
            <div className="flex-1 mb-8">
              <h3 className="text-lg font-semibold text-neutral-dark dark:text-white mb-4">
                Key Points
              </h3>
              <ul className="space-y-3">
                {content.keyPoints.map((point, index) => (
                  <li key={index} className="flex items-start gap-3">
                    <CheckCircle2 className="w-5 h-5 text-primary dark:text-primary-light flex-shrink-0 mt-0.5" />
                    <span className="text-neutral-dark/70 dark:text-white/70">{point}</span>
                  </li>
                ))}
              </ul>
            </div>
          )}
          {content.link && (
            <motion.a
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
              href={content.link}
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center px-6 py-3 bg-primary text-white rounded-full hover:bg-primary-dark transition-colors mt-4"
            >
              View {type === 'article' ? 'Original Article' : 'Project'}
              <ExternalLink className="w-4 h-4 ml-2" />
            </motion.a>
          )}
        </div>
      </div>

      {'video' in content && content.video && <VideoEmbed url={content.video} />}

      {content.mainContent && (
        <div className="prose prose-lg dark:prose-invert w-full max-w-none">
          <ReactMarkdown remarkPlugins={[remarkGfm]}>{content.mainContent}</ReactMarkdown>
        </div>
      )}
    </>
  );
}
