import { User } from 'lucide-react';

interface ProfileImageProps {
  src?: string;
  alt: string;
  className?: string;
  size?: 'sm' | 'md' | 'lg';
}

const sizeClasses = {
  sm: 'w-8 h-8',
  md: 'w-12 h-12',
  lg: 'w-16 h-16',
};

export default function ProfileImage({ src, alt, className = '', size = 'md' }: ProfileImageProps) {
  const sizeClass = sizeClasses[size];

  if (!src) {
    return (
      <div
        className={`${sizeClass} bg-gray-100 dark:bg-gray-800 rounded-full flex items-center justify-center ${className}`}
      >
        <User className="w-1/2 h-1/2 text-gray-400" />
      </div>
    );
  }

  return (
    <img
      src={src}
      alt={alt}
      className={`${sizeClass} rounded-full object-cover ${className}`}
      onError={e => {
        const target = e.target as HTMLImageElement;
        target.onerror = null; // Prevent infinite loop
        target.src =
          'https://dhqvfqbjomlbupcfatxz.supabase.co/storage/v1/object/public/images/default-avatar.jpg';
      }}
    />
  );
}
