import { useParams, Link } from 'react-router-dom';

import LoadingSpinner from '../components/common/LoadingSpinner';
import ContentPageComponent from '../components/Content/ContentPage';
import SEO from '../components/SEO';
import { useArticle } from '../hooks/useArticle';
import { useProject } from '../hooks/useProject';

interface ContentPageProps {
  type: 'article' | 'project';
}

export default function ContentPage({ type }: ContentPageProps) {
  const { id } = useParams<{ id: string }>();

  // Call both hooks unconditionally (rules of hooks) -- enabled/disabled via empty string
  const {
    article,
    isLoading: articleLoading,
    error: articleError,
  } = useArticle(type === 'article' && id ? id : '');
  const {
    project,
    isLoading: projectLoading,
    error: projectError,
  } = useProject(type === 'project' && id ? id : '');

  const content = type === 'article' ? article : project;
  const isLoading = type === 'article' ? articleLoading : projectLoading;
  const error = type === 'article' ? articleError : projectError;

  if (isLoading) {
    return (
      <div className="min-h-screen pt-24">
        <div className="container mx-auto px-6">
          <LoadingSpinner />
        </div>
      </div>
    );
  }

  if (error || !content) {
    return (
      <div className="min-h-screen pt-24">
        <div className="container mx-auto px-6">
          <div className="text-center">
            <h1 className="text-2xl font-bold mb-4 text-neutral-dark dark:text-white">
              {error
                ? `Error loading ${type}`
                : `${type === 'article' ? 'Article' : 'Project'} not found`}
            </h1>
            {error && (
              <p className="text-neutral-dark/70 dark:text-white/70 mb-4">{error.message}</p>
            )}
            <Link to="/" className="text-primary hover:text-primary-dark">
              Return home
            </Link>
          </div>
        </div>
      </div>
    );
  }

  return (
    <>
      <SEO
        title={`${content.title} | REWI.RE`}
        description={content.description}
        image={content.image}
        type={type === 'article' ? 'article' : 'website'}
        path={`/${type}s/${id}`}
        datePublished={content.date}
        authorName={type === 'article' && 'author' in content ? content.author?.name : undefined}
      />
      <ContentPageComponent content={content} type={type} />
    </>
  );
}
