import { Calendar, Clock } from 'lucide-react';

import type { Article, Project } from '../../types/common';
import ProfileImage from '../common/ProfileImage';

interface ContentMetadataProps {
  content: Article | Project;
  type: 'article' | 'project';
  formattedDate: string | null;
}

export default function ContentMetadata({ content, type, formattedDate }: ContentMetadataProps) {
  return (
    <>
      <div className="flex items-center gap-4 mb-6">
        {type === 'article' && 'publication' in content && (
          <span className="text-lg font-medium text-primary dark:text-primary-light">
            {content.publication}
          </span>
        )}
        {type === 'project' && 'client' in content && (
          <span className="text-lg font-medium text-primary dark:text-primary-light">
            {content.client}
          </span>
        )}
        {content.date && formattedDate && (
          <div className="flex items-center gap-2 text-neutral-dark/70 dark:text-white/70">
            <Calendar className="w-4 h-4" />
            <time dateTime={content.date}>{formattedDate}</time>
          </div>
        )}
        {'readTime' in content && content.readTime && (
          <div className="flex items-center gap-2 text-neutral-dark/70 dark:text-white/70">
            <Clock className="w-4 h-4" />
            <span>{content.readTime}</span>
          </div>
        )}
      </div>

      {type === 'article' && 'author' in content && content.author && (
        <div className="flex items-center gap-4 mb-8">
          <ProfileImage src={content.author.image} alt={content.author.name} size="lg" />
          <div>
            <div className="font-medium text-lg text-neutral-dark dark:text-white">
              {content.author.name}
            </div>
            {content.author.title && (
              <div className="text-neutral-dark/70 dark:text-white/70">{content.author.title}</div>
            )}
          </div>
        </div>
      )}
    </>
  );
}
