import { motion } from 'framer-motion';
import { ExternalLink } from 'lucide-react';
import { Link } from 'react-router-dom';

import type { Article, Project } from '../../types/common';
import { stripContentPrefix } from '../../utils/contentId';
import { optimizeImageUrl } from '../../utils/imageUrl';

interface RelatedContentProps {
  content: (Article | Project)[];
  type: 'article' | 'project';
  currentContentId: string;
}

export default function RelatedContent({ content, type, currentContentId }: RelatedContentProps) {
  // Filter out current content and limit to 3 items
  const relatedItems = content
    .filter(item => {
      const itemId = stripContentPrefix(item.id);
      return itemId !== currentContentId;
    })
    .slice(0, 3);

  if (!relatedItems.length) return null;

  return (
    <section className="mt-16">
      <h2 className="text-2xl font-bold text-neutral-dark dark:text-white mb-8">
        Related {type === 'article' ? 'Articles' : 'Projects'}
      </h2>

      <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
        {relatedItems.map((item, index) => (
          <motion.div
            key={item.id}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: index * 0.1 }}
            className="group bg-white dark:bg-neutral-dark rounded-xl overflow-hidden shadow-lg hover:shadow-xl transition-all"
          >
            <Link
              to={`/${type}s/${stripContentPrefix(item.id)}`}
              className="flex flex-col h-full"
              onClick={() => window.scrollTo(0, 0)}
            >
              <div className="relative aspect-video overflow-hidden">
                {item.image && (
                  <img
                    src={optimizeImageUrl(item.image, 800)}
                    alt={item.title}
                    className="w-full h-full object-cover transform group-hover:scale-110 transition-transform duration-500"
                    width={800}
                    height={450}
                    loading="lazy"
                    decoding="async"
                  />
                )}
                <div className="absolute inset-0 bg-gradient-to-t from-black/50 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
                <div className="absolute bottom-4 right-4 bg-white dark:bg-neutral-dark rounded-full p-2 opacity-0 group-hover:opacity-100 transform group-hover:translate-y-0 translate-y-4 transition-all duration-300">
                  <ExternalLink className="w-5 h-5 text-primary dark:text-primary-light" />
                </div>
              </div>

              <div className="flex-1 p-6">
                <div className="mb-2">
                  <span className="text-sm font-medium text-primary dark:text-primary-light">
                    {'publication' in item ? item.publication : item.client}
                  </span>
                </div>

                <h3 className="text-xl font-bold text-neutral-dark dark:text-white mb-2 group-hover:text-primary dark:group-hover:text-primary-light transition-colors line-clamp-2">
                  {item.title}
                </h3>

                <p className="text-neutral-dark/70 dark:text-white/70 line-clamp-2">
                  {item.description}
                </p>
              </div>
            </Link>
          </motion.div>
        ))}
      </div>
    </section>
  );
}
