import { motion } from 'framer-motion';
import { ArrowLeft } from 'lucide-react';
import React from 'react';
import { Link, useNavigate } from 'react-router-dom';

import { useFilteredContent } from '../../hooks/useFilteredContent';
import type { Article, Project } from '../../types/common';
import { scrollToTop } from '../../utils/scroll';
import { normalizeTag } from '../../utils/tagUtils';

import ContentBody from './ContentBody';
import ContentMetadata from './ContentMetadata';
import RelatedContent from './RelatedContent';

interface ContentPageProps {
  content: Article | Project;
  type: 'article' | 'project';
}

const ContentPage: React.FC<ContentPageProps> = ({ content, type }) => {
  const navigate = useNavigate();
  const formattedDate = content.date
    ? new Date(content.date).toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'long',
        day: 'numeric',
      })
    : null;

  // Get related content based on shared tags
  const { articles, projects } = useFilteredContent(content.tags || []);
  const relatedContent = (type === 'article' ? articles : projects).filter(
    item => item.id !== content.id
  );

  const handleTagClick = (tag: string) => {
    navigate(`/filtered/${normalizeTag(tag)}`);
    scrollToTop();
  };

  return (
    <div className="min-h-screen pt-24 pb-16 bg-gray-50 dark:bg-neutral-darker">
      <div className="container mx-auto px-6">
        <nav className="mb-8" aria-label="Breadcrumb">
          <Link
            to="/"
            onClick={scrollToTop}
            className="inline-flex items-center text-primary hover:text-primary-dark group"
          >
            <ArrowLeft className="w-4 h-4 mr-2 group-hover:-translate-x-1 transition-transform" />
            Back to {type === 'article' ? 'Articles' : 'Projects'}
          </Link>
        </nav>

        <motion.article
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-white dark:bg-neutral-dark rounded-2xl shadow-lg overflow-hidden mb-16"
        >
          <div className="p-8 md:p-12">
            <ContentMetadata content={content} type={type} formattedDate={formattedDate} />

            <h1 className="text-4xl md:text-5xl font-bold text-neutral-dark dark:text-white mb-6">
              {content.title}
            </h1>

            {content.headline && (
              <h2 className="text-2xl font-semibold text-neutral-dark/90 dark:text-white/90 mb-4">
                {content.headline}
              </h2>
            )}

            <div className="text-lg text-neutral-dark/60 dark:text-white/60 mb-8">
              {content.description}
            </div>

            <ContentBody content={content} type={type} onTagClick={handleTagClick} />
          </div>
        </motion.article>

        {relatedContent.length > 0 && (
          <RelatedContent content={relatedContent} type={type} currentContentId={content.id} />
        )}
      </div>
    </div>
  );
};

export default ContentPage;
