import { Video } from 'lucide-react';

interface VideoEmbedProps {
  url: string;
}

function getEmbedUrl(url: string): string {
  const youtubeRegex =
    /(?:youtube\.com\/(?:[^/]+\/.+\/|(?:v|e(?:mbed)?)\/|.*[?&]v=)|youtu\.be\/)([^"&?/\s]{11})/;
  const vimeoRegex =
    /(?:www\.|player\.)?vimeo.com\/(?:channels\/(?:\w+\/)?|groups\/(?:[^/]*)\/videos\/|video\/|)(\d+)(?:|\/\?)/;

  const match = url.match(youtubeRegex);
  const vimeoMatch = url.match(vimeoRegex);

  if (match && match[1]) {
    return `https://www.youtube.com/embed/${match[1]}`;
  }
  if (vimeoMatch && vimeoMatch[1]) {
    return `https://player.vimeo.com/video/${vimeoMatch[1]}`;
  }
  return url;
}

export default function VideoEmbed({ url }: VideoEmbedProps) {
  return (
    <div className="mb-12">
      <div className="flex items-center gap-2 mb-4">
        <Video className="w-5 h-5 text-primary dark:text-primary-light" />
        <h2 className="text-xl font-bold text-neutral-dark dark:text-white">Featured Video</h2>
      </div>
      <div className="relative aspect-video rounded-xl overflow-hidden shadow-lg">
        <iframe
          src={getEmbedUrl(url)}
          title="Featured Video"
          className="w-full h-full"
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; fullscreen"
          allowFullScreen
          loading="lazy"
        />
      </div>
    </div>
  );
}
